import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"融合意图应用（WP-l1apps-merge）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/merged-apps.md","filePath":"zh/l1/merged-apps.md"}'),a={name:"zh/l1/merged-apps.md"};function i(r,e,l,s,p,n){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="融合意图应用-wp-l1apps-merge" tabindex="-1">融合意图应用（WP-l1apps-merge） <a class="header-anchor" href="#融合意图应用-wp-l1apps-merge" aria-label="Permalink to &quot;融合意图应用（WP-l1apps-merge）&quot;">​</a></h1><p>WP-l1apps-merge 用八个意图驱动的大应用取代了&quot;每个 L1SVC 操作一个包装程序&quot;的散装格局。用户不再需要记忆 200 多条命令拼写：运行一个应用、从菜单选一个编号，向导就会替你驱动底层的 L0 服务——而且当某一步无法进行时，向导会提供自动修复路径（无 IP 时 DHCP、磁盘缺失时 A/B 初始化……）。</p><p>所有经典拼写继续可用（功能零损失）：合并前的一命令包装以三种形式存活——<code>direct &lt;词&gt; ...</code>（显式）、裸词直通（geek 模式），以及在不属于服务操作的场合作为独立程序存在（ls、cp 等）。</p><h2 id="八个应用" tabindex="-1">八个应用 <a class="header-anchor" href="#八个应用" aria-label="Permalink to &quot;八个应用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>应用</th><th>菜单域</th><th>向导修复</th></tr></thead><tbody><tr><td><code>update</code></td><td>OTA：网络 / A/B 磁盘 / <strong>更新源（镜像）</strong> / 检查 / 安装</td><td>DHCP、A/B 初始化</td></tr><tr><td><code>disk-tool</code></td><td>块设备、分区、mkfs、挂载、fsck、统计、A/B 管理</td><td>重输设备名确认</td></tr><tr><td><code>net-tool</code></td><td>IP、DHCP、静态 IP、DNS、WiFi、蓝牙、防火墙、路由、测试</td><td>DHCP</td></tr><tr><td><code>sound-tool</code></td><td>声卡检测、音量、播放、逐驱动状态、自检</td><td>-</td></tr><tr><td><code>files</code></td><td>ls / tree / df+du / cp / mv / rm / edit / stat+chmod，真实子进程</td><td>fork + exec + wait</td></tr><tr><td><code>sysdiag</code></td><td>内存、堆、碎片、调度器、健康、dmesg、logcat、崩溃日志、memtest</td><td>memtest 前确认</td></tr><tr><td><code>hwinfo</code></td><td>PCI、PCIe、磁盘、USB（+按槽位详情）、输入设备、I2C/SMBus</td><td>-</td></tr><tr><td><code>power</code></td><td>电源/ACPI 状态、看门狗、<strong>重启 / 关机 / 停机（每项都需裸 y 确认）</strong></td><td>-</td></tr></tbody></table><h2 id="向导如何驱动服务" tabindex="-1">向导如何驱动服务 <a class="header-anchor" href="#向导如何驱动服务" aria-label="Permalink to &quot;向导如何驱动服务&quot;">​</a></h2><p>桥接只有一个系统调用：<code>SYS_L1SVC(cat, op, arg, out, cap)</code>（110 号）。<code>ocos/interface/l1svc_ops.h</code> 是生成的操作号镜像；应用直接包含它并选用常量——无需注册、无需新的构建规则（<code>ocos/l1apps/&lt;名字&gt;/</code> 下含 <code>main.c</code> 加 <code>i18n/{en,zh}.json</code> 的目录会被 <code>tools/gen_userprogs.py</code> 自动发现）。</p><p><code>ocos/interface/wizard_lib.h</code> 是共享工具包（header-only，每个应用编译自己的拷贝）：</p><ul><li><code>wiz_svc(cat, op, arg)</code> 运行一个操作并原样打印捕获文本；<code>wiz_svc_quiet(..., out, cap)</code> 只捕获不打印。</li><li><code>wiz_find(hay, needle)</code> 探测 L0 服务输出的固定锚点子串（英文文本契约，跨版本稳定）：<code>A/B disk: present</code>、<code>IP: 0.0.0.0</code>、<code>New version available.</code>、<code>Current version is up to date.</code>。</li><li><code>wiz_token_after(...)</code> 提取值（<code>IP: 10.0.2.15</code> → 地址）。</li><li><code>wiz_ask</code> / <code>wiz_confirm</code> / <code>wiz_pause</code> / <code>wiz_menu</code>——输入层。所有等待都阻塞在内核行读取器上（SYS_READLINE，hlt 睡眠）：菜单选择输入 <code>&lt;数字&gt;&lt;回车&gt;</code>（或 <code>q</code>），确认只认裸 <code>y</code>。曾尝试 ring 3 忙轮询原始按键队列并已否决——每秒百万次 int-0x80 陷阱会在单 CPU 上饿死内核 tick 工作（net_poll / tcp_check_rto），系统连同轮询者一起卡死；见 KNOWN_ISSUES。</li></ul><h2 id="update-向导的镜像源步骤" tabindex="-1">update 向导的镜像源步骤 <a class="header-anchor" href="#update-向导的镜像源步骤" aria-label="Permalink to &quot;update 向导的镜像源步骤&quot;">​</a></h2><p><code>update</code> 的第 3 步显示当前源（<code>config get update_url</code>）并提供文档化镜像：</p><ol><li>官方源 - <code>https://cubestudio-dev.github.io/OpenCubeOS/update.json</code></li><li>GitHub raw 镜像 - <code>https://raw.githubusercontent.com/cubestudio-dev/OpenCubeOS/gh-pages/update.json</code></li><li>jsDelivr CDN 镜像 - <code>https://cdn.jsdelivr.net/gh/cubestudio-dev/OpenCubeOS@gh-pages/update.json</code></li><li>自定义 URL（校验必须以 <code>http://</code> 或 <code>https://</code> 开头）</li></ol><p>所选镜像通过 <code>config set update_url &lt;url&gt;</code> 持久化——与手工编辑相同的机制，没有任何魔法——随后向导解析当前 URL 中的主机名再进行检查。大文件永远不会压垮内存：服务端下载器（<code>ota_update_download</code>）以 4 KiB 分块流式写盘（DL_CHUNK），因此对远大于内存的文件同样有效。</p><h2 id="i18n-文件为什么重要" tabindex="-1">i18n 文件为什么重要 <a class="header-anchor" href="#i18n-文件为什么重要" aria-label="Permalink to &quot;i18n 文件为什么重要&quot;">​</a></h2><p>每个应用都带 <code>i18n/{en,zh}.json</code>；<code>tr_(&quot;key&quot;)</code> 渲染界面文本，未命中时回退为键本身，因此不完整的资源永远不会弄垮向导。每个融合应用必须自带的四个公共键：<code>wiz_quit</code>、<code>wiz_select</code>、<code>wiz_pause</code>、<code>wiz_svc_failed</code>。服务输出永不翻译——英文锚点就是向导解析的契约。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ul><li><code>tools/wp_wizard_test.py</code>——QEMU 下 <code>update</code> 状态机端到端（网络步骤、A/B 引导、行读取器回显、不一致中止，6/6）。</li><li><code>tools/wp_smoke_test.py</code>——每个应用响应菜单（<code>q</code> 退出）及其直通词；11/11。</li><li>全闭环证据：一次真实 QEMU 运行走完 DHCP → abdisk 初始化 → 镜像写入 /etc/opencube.conf → DNS 185.185.109.153 → 对真实 GitHub Pages 清单返回 <code>Current version is up to date.</code>。</li></ul><p>测试期的已知限制：向本 QEMU 构建挂载第二块磁盘（IDE 或 virtio）会以内核 tick 工作饿死客户机——向导本身行为正确（状态机测试不挂附加盘运行）；该现象已记录在 KNOWN_ISSUES.md。</p>',18)])])}const _=t(a,[["render",i]]);export{h as __pageData,_ as default};
